import React, { useEffect, useRef, useState } from "react";
import {
  REPORT_REASONS,
  bumpPlays,
  deleteSave,
  isFavorited,
  loadSetting,
  reportWorld,
  setFavorite,
} from "../lib/db";
import { useNarrow } from "../hooks";
import { T, inputStyle } from "../theme";
import { Btn, Empty, Splash } from "../ui/primitives";

export function GameDetail({ game, chars, saves, setSaves, userId, defaultCharacterId, go, from = "browse", isMine, isGuest, guestName }) {
  // No more picking who to play as here — that's now chosen once, from
  // the profile settings page. Falls back to chars[0] (the un-deletable
  // default character) if nothing's been explicitly chosen yet.
  const picked = defaultCharacterId ?? chars[0]?.id ?? null;
  const [reporting, setReporting] = useState(false);
  const [confirmNewGame, setConfirmNewGame] = useState(false);
  const [startingNew, setStartingNew] = useState(false);
  const [favorited, setFavorited] = useState(null);
  const [showStory, setShowStory] = useState(false);
  const [crawlDistance, setCrawlDistance] = useState(null); // px — measured, not guessed
  const crawlTextRef = useRef(null);
  const crawlFrameRef = useRef(null);
  const narrow = useNarrow();
  if (!game) return <Empty title="That world is gone." line="It may have been unpublished by its author." />;
  const save = saves[`${game.id}:${picked}`];

  const wordCount = (game.storyDetails ?? "").trim().split(/\s+/).filter(Boolean).length;
  // TEMPORARY — for dialing in the right feel by hand. Remove this
  // state, the localStorage read/write effect, and the slider/selector
  // UI below once settled, and hardcode the chosen values directly into
  // crawlSeconds/fontFamily/color instead.
  const readDebug = (key, fallback) => {
    try {
      const v = localStorage.getItem(`story_crawl_debug_${key}`);
      return v !== null ? JSON.parse(v) : fallback;
    } catch { return fallback; }
  };
  const hasLocalOverride = (key) => {
    try { return localStorage.getItem(`story_crawl_debug_${key}`) !== null; } catch { return false; }
  };
  const [debugWordsPerSec, setDebugWordsPerSec] = useState(() => readDebug("wordsPerSec", 2.9));
  const [debugFontSize, setDebugFontSize] = useState(() => readDebug("fontSize", 3.00));
  const [debugFont, setDebugFont] = useState(() => readDebug("font", "mono"));
  const [debugColor, setDebugColor] = useState(() => readDebug("color", "bone"));
  // Hidden by default — an admin can turn this back on globally from
  // Admin → Settings → Story crawl, for everyone, not just themselves.
  const [debugPanelVisible, setDebugPanelVisible] = useState(false);
  useEffect(() => {
    loadSetting("story_crawl_debug_visible").then((v) => setDebugPanelVisible(Boolean(v?.visible))).catch(() => {});
    // The admin's saved global defaults were being written correctly
    // but never actually read anywhere — this is what makes a change
    // made in Admin → Story crawl actually reach a player. Only applied
    // per-setting where there's no local override already in
    // localStorage, so a browser mid-testing with the debug sliders
    // still keeps its own values rather than being overwritten.
    loadSetting("story_crawl_defaults").then((v) => {
      if (!v) return;
      if (typeof v.wordsPerSec === "number" && !hasLocalOverride("wordsPerSec")) setDebugWordsPerSec(v.wordsPerSec);
      if (typeof v.fontSize === "number" && !hasLocalOverride("fontSize")) setDebugFontSize(v.fontSize);
      if (typeof v.font === "string" && !hasLocalOverride("font")) setDebugFont(v.font);
      if (typeof v.color === "string" && !hasLocalOverride("color")) setDebugColor(v.color);
    }).catch(() => {});
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem("story_crawl_debug_wordsPerSec", JSON.stringify(debugWordsPerSec));
      localStorage.setItem("story_crawl_debug_fontSize", JSON.stringify(debugFontSize));
      localStorage.setItem("story_crawl_debug_font", JSON.stringify(debugFont));
      localStorage.setItem("story_crawl_debug_color", JSON.stringify(debugColor));
    } catch {}
  }, [debugWordsPerSec, debugFontSize, debugFont, debugColor]);

  const CRAWL_FONTS = {
    mono: { label: "Mono (platform default)", css: T.mono },
    imfell: { label: "IM Fell English", css: "'IM Fell English', Georgia, serif" },
    germania: { label: "Germania One", css: "'Germania One', serif" },
    vt323: { label: "VT323", css: "'VT323', monospace" },
    jacquard: { label: "Jacquard 12", css: "'Jacquard 12', serif" },
    coral: { label: "Coral Pixels", css: "'Coral Pixels', sans-serif" },
    jersey10: { label: "Jersey 10", css: "'Jersey 10', sans-serif" },
    jersey15: { label: "Jersey 15", css: "'Jersey 15', sans-serif" },
  };

  const crawlSeconds = Math.min(100, Math.max(9, wordCount / debugWordsPerSec));

  const startStory = () => {
    if (!game.storyDetails) return;
    setCrawlDistance(null);
    setShowStory(true);
    if (window.speechSynthesis) {
      window.speechSynthesis.cancel(); // clears anything left over from a previous run
      window.speechSynthesis.speak(new SpeechSynthesisUtterance(game.storyDetails));
    }
  };

  // Measures the real rendered height of both the text and the frame
  // once the crawl text is actually in the DOM, then computes exactly
  // how far it needs to travel to fully clear the top — rather than a
  // fixed, generous distance that overshoots for anything shorter than
  // the longest reasonable story, leaving dead animation time after the
  // text has already visually disappeared before onAnimationEnd fires.
  useEffect(() => {
    if (!showStory || !crawlTextRef.current || !crawlFrameRef.current) return;
    const textH = crawlTextRef.current.offsetHeight;
    setCrawlDistance(textH);
  }, [showStory]);

  // No hold anymore — fades back the moment the crawl genuinely ends
  // (a real CSS animationend event), not after an extra wait on top.
  const onCrawlEnd = () => {
    setShowStory(false);
  };

  // Speech shouldn't keep going after the player leaves this page.
  useEffect(() => {
    return () => { if (window.speechSynthesis) window.speechSynthesis.cancel(); };
  }, []);

  useEffect(() => {
    if (!userId) return;
    isFavorited(userId, game.id).then(setFavorited).catch(() => {});
  }, [userId, game.id]);

  const toggleFavorite = async () => {
    const next = !favorited;
    setFavorited(next); // optimistic
    try {
      await setFavorite(userId, game.id, next);
    } catch {
      setFavorited(!next); // revert on failure
    }
  };

  // Discards the existing save and jumps straight into a fresh one —
  // the old separate Reset button only ever cleared the save and left
  // the player back on this page; this is strictly more useful, so it
  // replaces that rather than sitting alongside it.
  // Shared by both Start and Continue — a guest with no name set yet is
  // routed through the prompt first, then straight into play once it's
  // set; a returning guest (name already in localStorage) or any
  // signed-in player goes straight in, unchanged from before.
  const playOrPromptForName = () => {
    bumpPlays(game.id);
    if (isGuest && !guestName) {
      go("guestName", { returnTo: { name: "play", id: game.id } });
      return;
    }
    go("play", { id: game.id, charId: picked });
  };

  const startNewGame = async () => {
    if (!picked) return;
    setStartingNew(true);
    try {
      await deleteSave(userId, game.id, picked);
      setSaves((s) => {
        const next = { ...s };
        delete next[`${game.id}:${picked}`];
        return next;
      });
      bumpPlays(game.id);
      go("play", { id: game.id, charId: picked });
    } catch (e) {
      console.error(e);
      setStartingNew(false);
    }
  };

  return (
    <div className="pf-in">
      <Btn kind="ghost" onClick={() => go(from)} style={{ marginBottom: 14 }}>back</Btn>

      {/* the splash screen leads, full width, before anything is said about it */}
      <div ref={crawlFrameRef} style={{ position: "relative", width: "100%", paddingTop: "56.25%",
        containerType: "inline-size", borderRadius: 2, overflow: "hidden", marginBottom: 26 }}>
        <div style={{ position: "absolute", inset: 0, opacity: showStory ? 0 : 1,
          transition: "opacity 900ms ease", pointerEvents: showStory ? "none" : "auto" }}>
          <Splash seed={game.id} src={game.coverUrl} ratio={0.5625} />
        </div>

        {game.storyDetails && (
          <div style={{ position: "absolute", inset: 0, background: "#0a0b10", overflow: "hidden",
            opacity: showStory ? 1 : 0, transition: "opacity 900ms ease",
            pointerEvents: showStory ? "auto" : "none" }}>
            {showStory && (
              <p ref={crawlTextRef} onAnimationEnd={crawlDistance ? onCrawlEnd : undefined}
                style={{ position: "absolute", left: 0, right: 0, top: "100%", margin: 0, padding: "0 32px",
                  textAlign: "center", fontFamily: CRAWL_FONTS[debugFont].css, fontSize: `${debugFontSize}cqw`, lineHeight: 1.7,
                  WebkitTextSizeAdjust: "100%", textSizeAdjust: "100%",
                  color: debugColor === "bone" ? T.bone : T.ochre, whiteSpace: "pre-wrap",
                  ...(crawlDistance
                    ? { "--crawl-distance": `${crawlDistance}px`, animation: `story-crawl ${crawlSeconds}s linear forwards` }
                    : {}) }}>
                {game.storyDetails}
              </p>
            )}
          </div>
        )}

        <style>{`
          @font-face {
            font-family: 'IM Fell English';
            src: url('/fonts/IMFellEnglish-Regular.ttf') format('truetype');
            font-display: swap;
          }
          @font-face {
            font-family: 'Germania One';
            src: url('/fonts/GermaniaOne-Regular.ttf') format('truetype');
            font-display: swap;
          }
          @font-face {
            font-family: 'VT323';
            src: url('/fonts/VT323-Regular.ttf') format('truetype');
            font-display: swap;
          }
          @font-face {
            font-family: 'Jacquard 12';
            src: url('/fonts/Jacquard12-Regular.ttf') format('truetype');
            font-display: swap;
          }
          @font-face {
            font-family: 'Coral Pixels';
            src: url('/fonts/CoralPixels-Regular.ttf') format('truetype');
            font-display: swap;
          }
          @font-face {
            font-family: 'Jersey 10';
            src: url('/fonts/Jersey10-Regular.ttf') format('truetype');
            font-display: swap;
          }
          @font-face {
            font-family: 'Jersey 15';
            src: url('/fonts/Jersey15-Regular.ttf') format('truetype');
            font-display: swap;
          }
          @keyframes story-crawl {
            from { top: 100%; }
            to   { top: calc(-1 * var(--crawl-distance)); }
          }
        `}</style>
      </div>

      <div style={{ display: "grid", gap: narrow ? 26 : 34, alignItems: "start",
        gridTemplateColumns: narrow ? "1fr" : "minmax(0, 1.5fr) minmax(240px, 1fr)" }}>

        <div>
          <h1 style={{ fontFamily: T.serif, fontSize: 32, fontWeight: 400, margin: "0 0 8px", lineHeight: 1.15 }}>
            {game.title}
          </h1>
          <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, marginBottom: 16 }}>
            {game.author?.startsWith("@") ? (
              <button className="pf-btn"
                onClick={() => go("creatorProfile", { username: game.author.slice(1) })}
                style={{ background: "none", border: "none", padding: 0, font: "inherit", color: "inherit", cursor: "pointer" }}>
                {game.author}
              </button>
            ) : game.author} &middot; {game.rooms} rooms &middot; {game.mobs} characters
            &middot; {game.plays.toLocaleString()} plays
          </div>
          <p style={{ fontFamily: T.serif, fontSize: 17, lineHeight: 1.62, margin: 0 }}>{game.blurb}</p>
        </div>

        <div>
          <div style={{ fontFamily: T.serif, fontSize: 15, marginBottom: 8 }}>Play as</div>
          <div style={{ display: "flex", gap: 8, marginBottom: 20 }}>
            <button className="pf-btn"
              onClick={() => isGuest
                ? go("guestName", { returnTo: { name: "game", id: game.id, from } })
                : go("profile")}
              title={isGuest ? "Set or change your name" : "Change who you play as from your profile settings"}
              style={{ fontFamily: T.mono, fontSize: 12, padding: "8px 13px", cursor: "pointer", borderRadius: 2,
                background: "transparent", color: T.bone, border: "1px solid " + T.ochre }}>
              {isGuest ? (guestName || "set your name") : (chars.find((c) => c.id === picked)?.name ?? "\u2014")}
            </button>
            {game.storyDetails && (
              <button className="pf-btn" onClick={startStory}
                style={{ fontFamily: T.mono, fontSize: 12, padding: "8px 13px", cursor: "pointer", borderRadius: 2,
                  background: "transparent", color: T.bone, border: "1px solid " + T.edge }}>
                Story
              </button>
            )}
            {userId && (
              <button className="pf-btn" onClick={toggleFavorite}
                style={{ marginLeft: "auto", fontFamily: T.mono, fontSize: 12, padding: "8px 13px",
                  cursor: "pointer", borderRadius: 2, background: "transparent",
                  color: favorited ? T.moss : T.clay, border: "1px solid " + (favorited ? T.moss : T.clay) }}>
                {favorited ? "favorited" : "favorite"}
              </button>
            )}
          </div>

          {/* TEMPORARY — delete this whole block once settled, and
              hardcode debugWordsPerSec/debugFontSize/debugFont/debugColor's
              chosen values directly into crawlSeconds/fontFamily/color. */}
          {game.storyDetails && !showStory && debugPanelVisible && (
            <div style={{ border: "1px dashed " + T.edge, borderRadius: 2, padding: 10, marginBottom: 20 }}>
              <div style={{ fontFamily: T.mono, fontSize: 10, color: T.clay, marginBottom: 8 }}>
                TEMP — crawl tuning
              </div>
              <label style={{ display: "block", fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginBottom: 6 }}>
                Speed: {debugWordsPerSec.toFixed(1)} words/sec
                <input type="range" min="0.3" max="5" step="0.1" value={debugWordsPerSec}
                  onChange={(e) => setDebugWordsPerSec(Number(e.target.value))}
                  style={{ display: "block", width: "100%" }} />
              </label>
              <label style={{ display: "block", fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>
                Font size: {debugFontSize.toFixed(2)}cqw (scales with frame width)
                <input type="range" min="1.5" max="6" step="0.05" value={debugFontSize}
                  onChange={(e) => setDebugFontSize(Number(e.target.value))}
                  style={{ display: "block", width: "100%" }} />
              </label>
              <label style={{ display: "block", fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginTop: 10 }}>
                Font
                <select value={debugFont} onChange={(e) => setDebugFont(e.target.value)}
                  style={{ ...inputStyle, display: "block", width: "100%", marginTop: 4 }}>
                  {Object.entries(CRAWL_FONTS).map(([key, f]) => (
                    <option key={key} value={key}>{f.label}</option>
                  ))}
                </select>
              </label>
              <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginTop: 10, marginBottom: 4 }}>
                Color
              </div>
              <div style={{ display: "flex", gap: 6 }}>
                {[["ochre", "Accent (ochre)"], ["bone", "Bone"]].map(([k, label]) => (
                  <button key={k} className="pf-btn" onClick={() => setDebugColor(k)}
                    style={{ fontFamily: T.mono, fontSize: 11, padding: "5px 10px", cursor: "pointer", borderRadius: 2,
                      background: "transparent", color: debugColor === k ? T.bone : T.boneDim,
                      border: "1px solid " + (debugColor === k ? T.ochre : T.edge) }}>
                    {label}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginBottom: 20, minHeight: 16 }}>
            {save ? `turn ${save.state.turn} \u2014 picks up where they left off`
              : (picked || isGuest) ? "new game"
              : "make a character on your profile first"}
          </div>

          {confirmNewGame && save ? (
            <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, lineHeight: 1.7 }}>
              This deletes your progress on this world for this character — turn {save.state.turn},
              gone for good. There is no undo.
              <div style={{ display: "flex", gap: 10, marginTop: 8 }}>
                <Btn kind="solid" disabled={startingNew} onClick={startNewGame}>
                  {startingNew ? "starting\u2026" : "Yes, start over"}
                </Btn>
                <Btn kind="ghost" onClick={() => setConfirmNewGame(false)}>Never mind</Btn>
              </div>
            </div>
          ) : (
            <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
              {save ? (
                <>
                  <Btn kind="ghost" disabled={(!picked && !isGuest) || !game.playable} onClick={() => setConfirmNewGame(true)}>
                    New game
                  </Btn>
                  <Btn kind="solid" disabled={(!picked && !isGuest) || !game.playable} onClick={playOrPromptForName}>
                    Continue
                  </Btn>
                </>
              ) : (
                <Btn kind="solid" disabled={(!picked && !isGuest) || !game.playable} onClick={playOrPromptForName}>
                  Start
                </Btn>
              )}
              {isMine && <Btn onClick={() => go("edit", { id: game.id })}>Edit</Btn>}
              {!isMine && (
                <Btn kind="ghost" onClick={() => setReporting((v) => !v)}>
                  {reporting ? "cancel" : "report"}
                </Btn>
              )}
            </div>
          )}

          {!game.playable && (
            <div style={{ fontFamily: T.mono, fontSize: 11, color: T.clay, marginTop: 12, lineHeight: 1.6 }}>
              {game.status === "generating" ? "Still being built. Check back in a minute."
                : game.status === "failed" ? (game.failureNote || "This world failed to build.")
                : "This world isn't finished yet."}
            </div>
          )}
          {reporting && <ReportBox worldId={game.id} onDone={() => setReporting(false)} />}

          {isMine && !game.published && game.playable && (
            <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginTop: 12, lineHeight: 1.6 }}>
              A draft. Only you can see this until you publish it from Edit.
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* ---------- edit ---------- */

export function ReportBox({ worldId, onDone }) {
  const [reason, setReason] = useState(REPORT_REASONS[0]);
  const [detail, setDetail] = useState("");
  const [busy, setBusy] = useState(false);
  const [sent, setSent] = useState(false);
  const [error, setError] = useState(null);

  const send = async () => {
    setBusy(true); setError(null);
    try {
      await reportWorld(worldId, reason, detail);
      setSent(true);
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  if (sent) {
    return (
      <div style={{ border: "1px solid " + T.edge, borderRadius: 2, padding: 16, marginTop: 16 }}>
        <p style={{ fontFamily: T.serif, fontSize: 15, lineHeight: 1.6, margin: 0, color: T.boneDim }}>
          Thank you. Somebody will look at it. You can keep playing in the meantime.
        </p>
      </div>
    );
  }

  return (
    <div style={{ border: "1px solid " + T.edge, borderRadius: 2, padding: 16, marginTop: 16 }}>
      <div style={{ fontFamily: T.serif, fontSize: 16, marginBottom: 10 }}>What is wrong with it?</div>

      <div style={{ display: "grid", gap: 5, marginBottom: 12 }}>
        {REPORT_REASONS.map((r) => (
          <button key={r} className="pf-btn" onClick={() => setReason(r)}
            style={{ textAlign: "left", padding: "7px 10px", borderRadius: 2, cursor: "pointer",
              background: "transparent", fontFamily: T.mono, fontSize: 12,
              color: reason === r ? T.bone : T.boneDim,
              border: "1px solid " + (reason === r ? T.ochre : T.edge) }}>
            {r}
          </button>
        ))}
      </div>

      <textarea
        value={detail}
        onChange={(e) => setDetail(e.target.value)}
        rows={3}
        placeholder="Where in the world is it, if that helps."
        style={{ ...inputStyle, fontSize: 13, lineHeight: 1.5, resize: "vertical", marginBottom: 12 }} />

      {error && (
        <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, margin: "0 0 12px" }}>{error}</p>
      )}

      <div style={{ display: "flex", gap: 10 }}>
        <Btn kind="solid" onClick={send} disabled={busy}>{busy ? "\u2026" : "Send"}</Btn>
        <Btn kind="ghost" onClick={onDone}>Cancel</Btn>
      </div>
    </div>
  );
}
