import React, { useState, useEffect } from "react";
import {
  DEFAULT_ART,
  ENGINES,
  PRICE_CENTS,
  deleteArt,
  drawArt,
  editArt,
  generateWithReference,
  loadArtConfig,
  loadArtPresetContent,
  loadArtPresetLabels,
  loadDefaultArtPreset,
  money,
  generateEndingArt,
  undoArtPrompt,
  previewArtPrompt,
  saveArtConfig,
  setArtLock,
  setArtPrompt,
  setArtPromptPixel,
  setArtLevels,
  swapArtVersions,
  uploadArt,
  uploadArtVideo,
  deleteArtVideo,
} from "../lib/db";
import { useNarrow } from "../hooks";
import { readable } from "../play/chrome";
import { roomBanner, fallbackSceneTag } from "../lib/svgScene";
import { T, inputStyle } from "../theme";
import { Glyph } from "../ui/icons";
import { Btn, Field, Splash } from "../ui/primitives";

// Rooms in this newer system don't carry explicit tags the way the
// scene generator expects (tavern/forest/market/etc.) — this infers a
// reasonable set by scanning the room's own name and description for
// the same words, rather than requiring a new schema field just for a
// placeholder. Falls through to the generator's own "default" palette
// if nothing matches, exactly as an empty tags array already would.
const SCENE_TAG_WORDS = [
  "tavern", "temple", "guild", "forest", "desert", "sea", "snow", "mountain", "ruins",
  "market", "fountain", "street", "gate", "dark",
];
function inferSceneTags(room) {
  const text = `${room?.name ?? ""} ${room?.desc ?? room?.prompt ?? ""}`.toLowerCase();
  const matched = SCENE_TAG_WORDS.filter((w) => text.includes(w));
  return matched.length ? matched : [fallbackSceneTag(room?.key ?? room?.id ?? "x")];
}
function sceneFallbackSvg(room) {
  return roomBanner(inferSceneTags(room), room?.key ?? room?.id ?? "x", 400, 225);
}

export const KINDS = [
  { key: "cover",  label: "Splash", ratio: 0.5625 },
  { key: "room",   label: "Rooms", ratio: 0.5625 },
  { key: "mob",    label: "Characters", ratio: 1.33 },
  { key: "prop",   label: "Props", ratio: 1 },
  { key: "item",   label: "Items", ratio: 1 },
  { key: "ending", label: "Ending", ratio: 0.5625 },
  { key: "badge",  label: "Badge", ratio: 1 },
];

// Items and splash screens are always Adventure v2: v1 is trained heavily on
// sprite sheets and fights a single object, and a titled splash needs type
// the model can actually render.

export const ENGINE_LOCKED = { item: "flux", prop: "flux", cover: "flux", ending: "flux" };

// Ending and badge are a creator's choice, same as rooms and characters —
// just biased toward Adventure v2 by default, since a conclusive scene or
// an emblem tends to want the same closely-directed, legible-text-capable
// look a splash screen does. Explicitly choosing Adventure v1 for either
// still works; this only decides what shows before anyone has chosen.
export const DEFAULT_ENGINE = { ending: "flux", badge: "flux" };

export const KIND_LABEL = { cover: "the splash screen", room: "rooms", mob: "characters", prop: "props", item: "items", ending: "the ending screen", badge: "the badge" };

export function ArtTab({ entries, setEntries, me, setMe, worldId, onDrawn, title }) {
  const isAdmin = Boolean(me?.isAdmin);
  const [kind, setKind] = useState("room");
  const [config, setConfig] = useState(null);
  const [suggestedConfig, setSuggestedConfig] = useState(null);   // the permanent, never-mutated AI suggestion — separate from config itself, so switching presets never loses it
  const [showStyle, setShowStyle] = useState(false);
  const [saved, setSaved] = useState(false);
  /* The prompt boxes are uncontrolled, so React will not repaint them when
     the config changes underneath. Bumping this remounts them, which is how
     a reset becomes visible rather than only being saved. */
  const [revision, setRevision] = useState(0);
  const [drawing, setDrawing] = useState(null);
  const [queue, setQueue] = useState([]);
  const [error, setError] = useState(null);
  const [editing, setEditing] = useState(null);   // artId whose prompt is open
  const [artPresets, setArtPresets] = useState([]);          // { id, label, sort_order } — no content, ever, for non-admins
  const [preview, setPreview] = useState(null);               // { id, config } — admin-only, read-only
  const [finalPreview, setFinalPreview] = useState({});       // { [artId]: { prompt, negative, settings } | "loading" | error string } — admin-only

  useEffect(() => {
    if (!worldId) return;
    let cancelled = false;
    loadArtConfig(worldId)
      .then((r) => { if (!cancelled) { setConfig(r.config); setSuggestedConfig(r.suggested); } })
      .catch(() => { if (!cancelled) setConfig({}); });
    return () => { cancelled = true; };
  }, [worldId]);

  const writeConfig = async (next, repaint = false) => {
    setConfig(next);
    if (repaint) setRevision((n) => n + 1);
    try {
      await saveArtConfig(worldId, next);
      setSaved(true);
      setTimeout(() => setSaved(false), 1600);
    } catch (e) { console.error(e); }
  };

  // Ending is locked to Adventure v2 (flux) — a completion scene is a
  // detailed, camera-directed prompt in its own right now, and flux is
  // specifically the engine that follows a written art direction closely
  // rather than reinterpreting it loosely. Badge keeps its own static
  // default too; there's no equivalent "which kind should it match" for
  // a small emblem.
  const engine = ENGINE_LOCKED[kind]
    ?? config?.[`engine_${kind}`]
    ?? DEFAULT_ENGINE[kind]
    ?? "pixel";
  const COST = PRICE_CENTS[engine] ?? 5;      // cents
  const styleKey = engine === "flux" ? "style_flux" : "style_pixel";

  // Presets are per engine, not per kind: one preset supplies framing and
  // negatives for every kind at once, the same way a world's own art style
  // is shared across kinds. Switching kinds within one engine keeps the
  // same preset selected; switching engines shows that engine's own list.
  useEffect(() => {
    let cancelled = false;
    // Labels only, for everyone — this is what a non-admin's browser is
    // ever allowed to know about a preset's existence.
    loadArtPresetLabels(engine).then((rs) => { if (!cancelled) setArtPresets(rs); }).catch(() => setArtPresets([]));
    setPreview(null);
    return () => { cancelled = true; };
  }, [engine]);

  // Badge gets its own key, separate from the shared preset_${engine}
  // every other kind uses — otherwise a preset chosen for, say, rooms
  // would silently also apply to badges, and a badge's own first-visit
  // default couldn't be independent of whatever else the world uses.
  const presetKey = kind === "badge" ? "preset_badge" : `preset_${engine}`;
  const selectedPreset = config?.[presetKey] ?? null;

  // Badge no longer offers Custom or Suggested at all — this catches
  // anything that already had one saved from before that restriction
  // existed, falling it back to Default rather than leaving a picker
  // with no button highlighted for an option nobody can select. Cover
  // (the splash screen) used to share this same restriction; it doesn't
  // anymore, so it's excluded from this check now.
  useEffect(() => {
    if (kind === "badge" && (selectedPreset === "custom" || selectedPreset === "suggested")) {
      chooseDefaultOption();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [kind, selectedPreset]);

  /* Three states, not two. "Custom" is a genuine opt-out: nothing is laid
     underneath, and a blank box sends a blank fragment — no fallback to
     the platform's own wording at all. "Default" is the dynamic one: it
     resolves at draw time to whichever preset the admin has marked
     default for this engine, or to the platform's original wording if
     nobody has. A named preset is unchanged from before. Only Custom
     leaves the boxes as they are; Default and a named preset both clear
     them, the same way, because both supply their own separate layer. */
  const clearBoxes = (extra) => writeConfig({
    ...config,
    ...extra,
    [styleKey]: "",
    [kind]: "",
    ...(engine === "pixel" ? { neg: "", [`neg_${kind}`]: "" } : {}),
  }, true);

  const chooseCustom = () => {
    writeConfig({ ...config, [presetKey]: "custom" });
    setPreview(null);
  };

  // Unlike chooseCustom, this actually restores the permanent
  // suggestion's text into the boxes — clicking it after the creator has
  // switched away (or edited Custom themselves) genuinely brings the
  // original AI-written style/framing back, not just the label.
  const chooseSuggested = () => {
    if (!suggestedConfig) return;
    writeConfig({
      ...config,
      [presetKey]: "suggested",
      style_flux: suggestedConfig.style_flux ?? config.style_flux,
      room: suggestedConfig.room ?? config.room,
      mob: suggestedConfig.mob ?? config.mob,
      prop: suggestedConfig.prop ?? config.prop,
      item: suggestedConfig.item ?? config.item,
    }, true);   // repaint — the boxes' own text just changed underneath them
    setPreview(null);
  };

  const chooseDefaultOption = () => {
    clearBoxes({ [presetKey]: null });
    if (!isAdmin) { setPreview(null); return; }
    // A real preset row stores one "style" field, since it already belongs
    // to one engine. The platform's own defaults keep the historical
    // style_pixel/style_flux split, so the fallback preview needs the
    // right one folded in under the same "style" key the render reads —
    // otherwise it always shows blank here regardless of engine, even
    // though the actual draw uses the correct text.
    const platformDefaults = { config: { ...DEFAULT_ART, style: DEFAULT_ART[styleKey] }, isPlatform: true };
    loadDefaultArtPreset(engine)
      .then((id) => id ? loadArtPresetContent(id).then((cfg2) => setPreview({ id, config: cfg2, isPlatform: false })) : setPreview(platformDefaults))
      .catch(() => setPreview(platformDefaults));
  };

  const choosePreset = (id) => {
    clearBoxes({ [presetKey]: id });
    if (isAdmin) {
      setPreview(null);
      loadArtPresetContent(id).then((cfg2) => setPreview({ id, config: cfg2, isPlatform: false })).catch(() => setPreview(null));
    }
  };

  const shown = kind === "orphan"
    ? entries.filter((e) => e.orphaned)
    : entries.filter((e) => e.kind === kind && !e.orphaned);
  const ratio = KINDS.find((k) => k.key === kind)?.ratio ?? 1;
  const missing = kind === "orphan" ? [] : shown.filter((e) => !e.art && !e.locked);
  const affordable = Math.floor(me.balance / COST);

  /* Which of the two slots (current/previous) each tile is showing. Not
     persisted — a reload always opens on "current", which is the natural
     default and avoids a database write for something this cosmetic. */
  const [viewing, setViewingState] = useState({});
  const isViewingPrev = (id) => viewing[id] === "previous";
  const [swapping, setSwapping] = useState(null);
  const [layout, setLayout] = useState("grid");   // not persisted; resets on reload
  const narrow = useNarrow();

  const draw = async (entry) => {
    if (entry.locked || drawing) return;
    setDrawing(entry.id);
    setError(null);
    try {
      const { url, balance_cents } = await drawArt(entry.id);
      // A redraw always pushes whatever was current down into previous,
      // so the "Undo" state is back to its starting point regardless of
      // what it was showing beforehand.
      setEntries((es) => es.map((e) => e.id === entry.id ? { ...e, prevUrl: e.url, url, art: true } : e));
      setViewingState((v) => ({ ...v, [entry.id]: "current" }));
      if (typeof balance_cents === "number") setMe((m) => ({ ...m, balance: balance_cents }));
      onDrawn?.();
    } catch (e) {
      setError(e.message);
      if (typeof e.balanceCents === "number") setMe((m) => ({ ...m, balance: e.balanceCents }));
      setQueue([]);          // stop the run rather than repeat the same failure
    } finally {
      setDrawing(null);
    }
  };

  const [uploading, setUploading] = useState(null);
  const [uploadingVideo, setUploadingVideo] = useState(null);
  const [removingVideo, setRemovingVideo] = useState(null);
  // Click-to-play, one at a time — clicking a different room's image
  // while a video is already playing switches to that one instead,
  // rather than stacking multiple videos loading at once.
  const [playingVideoFor, setPlayingVideoFor] = useState(null);
  const [advancedOpen, setAdvancedOpen] = useState({});   // { [entryId]: true }
  const [editOpen, setEditOpen] = useState({});           // { [entryId]: true }
  const [editText, setEditText] = useState({});           // { [entryId]: "typed instruction" }
  const [editReference, setEditReference] = useState({}); // { [entryId]: otherArtId } — kept separate
                                                            // from the Advanced section's own picker
  const [editReferenceOpen, setEditReferenceOpen] = useState({}); // { [entryId]: true }
  const [editingImage, setEditingImage] = useState(null); // entryId currently mid-edit
  const [editEngine, setEditEngine] = useState({}); // { [entryId]: "openai" | "fal" }, defaults to "openai"

  const editImage = async (entry) => {
    const instruction = (editText[entry.id] || "").trim();
    if (!instruction || editingImage) return;
    setEditingImage(entry.id);
    setError(null);
    try {
      const { url, balance_cents } = await editArt(
        entry.id, instruction, editReference[entry.id], editEngine[entry.id] || "openai");
      // Same undo mechanism as a normal redraw — what was current becomes
      // "previous", so Undo already works on an edit for free.
      setEntries((es) => es.map((e) => e.id === entry.id ? { ...e, prevUrl: e.url, url, art: true } : e));
      setViewingState((v) => ({ ...v, [entry.id]: "current" }));
      if (typeof balance_cents === "number") setMe((m) => ({ ...m, balance: balance_cents }));
      setEditText((t) => ({ ...t, [entry.id]: "" }));
      setEditReference((s) => ({ ...s, [entry.id]: "" }));
      setEditReferenceOpen((s) => ({ ...s, [entry.id]: false }));
      setEditOpen((s) => ({ ...s, [entry.id]: false }));
      onDrawn?.();
    } catch (e) {
      setError(e.message);
      if (typeof e.balanceCents === "number") setMe((m) => ({ ...m, balance: e.balanceCents }));
    } finally {
      setEditingImage(null);
    }
  };

  const EDIT_COST_CENTS = 12;              // matches the server's own PRICE_CENTS.edit default
  const EDIT_REFERENCE_COST_CENTS = 15;    // matches PRICE_CENTS.editWithReference default

  const [referencePicked, setReferencePicked] = useState({});   // { [entryId]: otherArtId }
  const [referencePointer, setReferencePointer] = useState({}); // { [entryId]: "who to match, if ambiguous" }
  const [generatingWithRef, setGeneratingWithRef] = useState(null);

  const useReference = async (entry) => {
    const refId = referencePicked[entry.id];
    if (!refId || generatingWithRef) return;
    setGeneratingWithRef(entry.id);
    setError(null);
    try {
      const { url, balance_cents } = await generateWithReference(entry.id, refId, referencePointer[entry.id]);
      setEntries((es) => es.map((e) => e.id === entry.id ? { ...e, prevUrl: e.url, url, art: true } : e));
      setViewingState((v) => ({ ...v, [entry.id]: "current" }));
      if (typeof balance_cents === "number") setMe((m) => ({ ...m, balance: balance_cents }));
      onDrawn?.();
    } catch (e) {
      setError(e.message);
      if (typeof e.balanceCents === "number") setMe((m) => ({ ...m, balance: e.balanceCents }));
    } finally {
      setGeneratingWithRef(null);
    }
  };

  const [regeneratingPromptFor, setRegeneratingPromptFor] = useState(null); // artId currently regenerating
  const [promptNote, setPromptNote] = useState({});                         // { [artId]: note text }

  const upload = async (entry, file) => {
    if (!file) return;
    setUploading(entry.id);
    setError(null);
    try {
      const { url, prev_url } = await uploadArt(entry.id, file);
      setEntries((es) => es.map((e) => e.id === entry.id ? { ...e, url, prevUrl: prev_url, art: true } : e));
      setViewingState((v) => ({ ...v, [entry.id]: "current" }));
    } catch (e) {
      setError(e.message);
    } finally {
      setUploading(null);
    }
  };

  const uploadVideo = async (entry, file) => {
    if (!file) return;
    setUploadingVideo(entry.id);
    setError(null);
    try {
      const { videoUrl } = await uploadArtVideo(entry.id, file);
      setEntries((es) => es.map((e) => e.id === entry.id ? { ...e, videoUrl, hasVideo: true } : e));
    } catch (e) {
      setError(e.message);
    } finally {
      setUploadingVideo(null);
    }
  };

  const removeVideo = async (entry) => {
    setRemovingVideo(entry.id);
    setError(null);
    try {
      await deleteArtVideo(entry.id);
      setEntries((es) => es.map((e) => e.id === entry.id ? { ...e, videoUrl: null, hasVideo: false } : e));
    } catch (e) {
      setError(e.message);
    } finally {
      setRemovingVideo(null);
    }
  };

  /* For a world built before endingScene/badgeEssence existed — writes a
     new prompt straight into this one entry (ending or badge, whichever
     was clicked) from the world's actual premise and quest structure.
     The old prompt is kept as prevPrompt rather than discarded, the same
     way a redrawn image keeps its previous version, so it can be undone.
     Only the stored text changes; an already-drawn picture keeps showing
     the old one until redrawn. */
  const regeneratePrompt = async (entry, target) => {
    setRegeneratingPromptFor(entry.id);
    setPromptNote((n) => ({ ...n, [entry.id]: null }));
    setError(null);
    try {
      const { prompt } = await generateEndingArt(worldId, target);
      setEntries((es) => es.map((e) => e.id === entry.id ? { ...e, prompt, prevPrompt: e.prompt } : e));
      setRevision((r) => r + 1); // uncontrolled textarea — this remounts it with the new text
      setPromptNote((n) => ({ ...n, [entry.id]: "New prompt written. Redraw to see it reflected." }));
    } catch (e) {
      setError(e.message);
    } finally {
      setRegeneratingPromptFor(null);
    }
  };

  const undoPrompt = async (entry) => {
    setError(null);
    try {
      const restored = await undoArtPrompt(entry.id);
      setEntries((es) => es.map((e) => e.id === entry.id ? { ...e, prompt: restored, prevPrompt: e.prompt } : e));
      setRevision((r) => r + 1);
      setPromptNote((n) => ({ ...n, [entry.id]: null }));
    } catch (e) {
      setError(e.message);
    }
  };

  /* Undo/redo. A real, persisted swap — not just what this tab happens to
     display — so the actual splash or portrait shown everywhere else in
     the app changes too, including the catalog cover for a splash screen.
     Free, instant. Works even on a locked entry: nothing is generated or
     spent, just which of two already-paid-for images is the current one. */
  const toggleViewing = async (entry) => {
    if (!entry.prevUrl || swapping) return;
    setSwapping(entry.id);
    setError(null);
    try {
      const { url, prev_url } = await swapArtVersions(entry.id);
      setEntries((es) => es.map((e) => e.id === entry.id ? { ...e, url, prevUrl: prev_url } : e));
      setViewingState((v) => ({ ...v, [entry.id]: isViewingPrev(entry.id) ? "current" : "previous" }));
    } catch (e) {
      setError(e.message);
    } finally {
      setSwapping(null);
    }
  };

  // Serial on purpose: the provider is slower under parallel load, and one
  // failure should stop the run rather than spend money on five more.
  useEffect(() => {
    if (drawing || !queue.length) return;
    const [next, ...rest] = queue;
    const entry = entries.find((e) => e.id === next);
    setQueue(rest);
    if (entry && !entry.art && !entry.locked) draw(entry);
  }, [queue, drawing]);

  const savePrompt = async (entry, prompt, isPixel) => {
    if (isPixel) {
      setEntries((es) => es.map((e) => e.id === entry.id ? { ...e, promptPixel: prompt } : e));
      try { await setArtPromptPixel(entry.id, prompt); } catch (e) { console.error(e); }
      return;
    }
    setEntries((es) => es.map((e) => e.id === entry.id ? { ...e, prompt } : e));
    try { await setArtPrompt(entry.id, prompt); } catch (e) { console.error(e); }
    // The preview reflects what is actually saved, the same thing a real
    // draw would use — refreshed here so it never shows stale text after
    // an edit, if it is currently open for this entry.
    if (finalPreview[entry.id] !== undefined) fetchFinalPreview(entry);
  };

  const setLevels = async (entry, themeLevel, peopleLevel) => {
    setEntries((es) => es.map((e) => e.id === entry.id ? { ...e, themeLevel, peopleLevel } : e));
    try { await setArtLevels(entry.id, themeLevel, peopleLevel); } catch (e) { console.error(e); }
    if (finalPreview[entry.id] !== undefined) fetchFinalPreview(entry);
  };

  const fetchFinalPreview = async (entry) => {
    setFinalPreview((p) => ({ ...p, [entry.id]: "loading" }));
    try {
      const result = await previewArtPrompt(entry.id);
      setFinalPreview((p) => ({ ...p, [entry.id]: result }));
    } catch (e) {
      setFinalPreview((p) => ({ ...p, [entry.id]: e.message }));
    }
  };

  const toggleFinalPreview = (entry) => {
    setFinalPreview((p) => {
      if (p[entry.id] !== undefined) {
        const { [entry.id]: _drop, ...rest } = p;
        return rest;
      }
      return p;
    });
    if (finalPreview[entry.id] === undefined) fetchFinalPreview(entry);
  };

  const toggleLock = async (entry) => {
    setEntries((es) => es.map((e) => e.id === entry.id ? { ...e, locked: !e.locked } : e));
    try { await setArtLock(entry.id, !entry.locked); } catch (e) { console.error(e); }
  };

  const busy = Boolean(drawing) || queue.length > 0;
  const batch = Math.min(missing.length, affordable);

  return (<>
    <div style={{ display: "flex", gap: 4, marginBottom: 16, flexWrap: "wrap" }}>
      {[...KINDS, { key: "orphan", label: "No longer here", ratio: 1 }].map((k) => {
        const n = k.key === "orphan"
          ? entries.filter((e) => e.orphaned).length
          : entries.filter((e) => e.kind === k.key && !e.orphaned).length;
        const done = k.key === "orphan"
          ? n
          : entries.filter((e) => e.kind === k.key && !e.orphaned && e.art).length;
        if (!n) return null;
        return (
          <button key={k.key} onClick={() => setKind(k.key)} className="pf-btn"
            style={{ background: "transparent", cursor: "pointer", padding: "7px 12px", borderRadius: 2,
              fontFamily: T.mono, fontSize: 12,
              color: kind === k.key ? T.bone : T.boneDim,
              border: "1px solid " + (kind === k.key ? T.ochre : T.edge) }}>
            {k.label}{k.key === "cover" ? (done ? " ✓" : "") : ` ${done}/${n}`}
          </button>
        );
      })}
    </div>

    <div style={{ border: `1px solid ${T.edge}`, borderRadius: 2, marginBottom: 18 }}>
      <button className="pf-btn" onClick={() => setShowStyle((v) => !v)}
        style={{ width: "100%", textAlign: "left", background: "transparent", border: "none", cursor: "pointer",
          padding: "11px 14px", fontFamily: T.mono, fontSize: 11.5, color: T.boneDim,
          display: "flex", alignItems: "center", gap: 10 }}>
        <span style={{ flex: 1 }}>{showStyle ? "hide" : "show"} art direction</span>
        {saved && <span style={{ color: T.moss }}>saved</span>}
      </button>

      {showStyle && config && (
        <div style={{ padding: "0 14px 16px" }}>
          <p style={{ fontFamily: T.serif, fontSize: 14.5, color: T.boneDim, lineHeight: 1.6, margin: "0 0 16px" }}>
            Every picture is drawn from three pieces joined together: the art style, the framing for
            its kind, and the description of the thing itself. The two boxes at the bottom say what
            to avoid. Changes save when you click away and apply to the next draw, not to pictures
            already made.
          </p>

          <Field
            label={`Engine for ${KIND_LABEL[kind] ?? kind}`}
            hint={ENGINE_LOCKED[kind]
              ? (kind === "item" || kind === "prop"
                  ? "Single objects always use Adventure v2. Adventure v1 is trained heavily on sprite sheets and fights one thing on its own."
                  : kind === "cover"
                    ? "The splash screen always uses Adventure v2, because the title has to be readable."
                    : "The ending screen always uses Adventure v2, since its prompt is a detailed, camera-directed scene that needs an engine which follows written direction closely rather than reinterpreting it loosely.")
              : ENGINES.find((x) => x.key === engine)?.note}>
            <div style={{ display: "flex", gap: 6 }}>
              {ENGINES.map((x) => {
                const locked = Boolean(ENGINE_LOCKED[kind]);
                const on = engine === x.key;
                return (
                  <button key={x.key} className="pf-btn"
                    disabled={locked}
                    onClick={() => writeConfig({ ...config, [`engine_${kind}`]: x.key })}
                    style={{ flex: 1, padding: "8px 10px", borderRadius: 2, fontFamily: T.mono, fontSize: 12,
                      cursor: locked ? "not-allowed" : "pointer",
                      opacity: locked && !on ? 0.35 : 1,
                      background: "transparent",
                      color: on ? T.bone : T.boneDim,
                      border: `1px solid ${on ? T.ochre : T.edge}` }}>
                    {x.label}
                  </button>
                );
              })}
            </div>
          </Field>

          <Field label={`Preset for ${ENGINES.find((x) => x.key === engine)?.label ?? engine}`}
            hint="Default and a named preset both clear the boxes below and attach their own text underneath instead; Custom leaves your boxes exactly as they are and adds nothing beneath them — a blank box sends a blank fragment.">
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              {kind !== "badge" && (
                <button className="pf-btn" onClick={chooseCustom}
                  title="Nothing else is added. A blank box sends nothing for that field."
                  style={{ padding: "8px 12px", borderRadius: 2, cursor: "pointer", background: "transparent",
                    fontFamily: T.mono, fontSize: 12, color: selectedPreset === "custom" ? T.bone : T.boneDim,
                    border: `1px solid ${selectedPreset === "custom" ? T.ochre : T.edge}` }}>
                  Custom
                </button>
              )}
              {kind !== "badge" && suggestedConfig && (
                <button className="pf-btn" onClick={chooseSuggested}
                  title="Written by the model for this world specifically when it was built. Click to bring that style and framing back into the boxes below, even if you've since switched away from it."
                  style={{ padding: "8px 12px", borderRadius: 2, cursor: "pointer", background: "transparent",
                    fontFamily: T.mono, fontSize: 12, color: selectedPreset === "suggested" ? T.bone : T.boneDim,
                    border: `1px solid ${selectedPreset === "suggested" ? T.ochre : T.edge}` }}>
                  Suggested
                </button>
              )}
              <button className="pf-btn" onClick={chooseDefaultOption}
                title="Whichever preset the admin has marked default for this engine, or the platform's original wording if none is set."
                style={{ padding: "8px 12px", borderRadius: 2, cursor: "pointer", background: "transparent",
                  fontFamily: T.mono, fontSize: 12, color: !selectedPreset ? T.bone : T.boneDim,
                  border: `1px solid ${!selectedPreset ? T.ochre : T.edge}` }}>
                Default
              </button>
              {artPresets.map((p) => (
                <button key={p.id} className="pf-btn" onClick={() => choosePreset(p.id)}
                  style={{ padding: "8px 12px", borderRadius: 2, cursor: "pointer", background: "transparent",
                    fontFamily: T.mono, fontSize: 12, color: selectedPreset === p.id ? T.bone : T.boneDim,
                    border: `1px solid ${selectedPreset === p.id ? T.ochre : T.edge}` }}>
                  {p.label}
                </button>
              ))}
            </div>
          </Field>

          {isAdmin && preview && (
            <div style={{ border: "1px solid " + T.ochre + "66", borderRadius: 2, padding: "12px 14px", marginBottom: 18,
              fontFamily: T.mono, fontSize: 11.5, lineHeight: 1.9, color: T.boneDim }}>
              <div style={{ color: T.ochre, marginBottom: 6 }}>
                {preview.isPlatform
                  ? "Platform original wording (admin only — no default preset is set for this engine)"
                  : "Preset content (admin only — nobody else ever downloads this)"}
              </div>
              <div><b style={{ color: T.bone }}>Art style:</b> {preview.config.style || "—"}</div>
              <div><b style={{ color: T.bone }}>Framing for {(KIND_LABEL[kind] ?? kind).toLowerCase()}:</b> {preview.config[kind] || "—"}</div>
              <div><b style={{ color: T.bone }}>Avoid, everywhere:</b> {preview.config.neg || "—"}</div>
              <div><b style={{ color: T.bone }}>Avoid, {(KIND_LABEL[kind] ?? kind).toLowerCase()} only:</b> {preview.config[`neg_${kind}`] || "—"}</div>
            </div>
          )}

          <Field label="Theme"
            hint="Shared across every picture in this world, regardless of engine — a short, broad genre label that gives the image model real leeway rather than pinning down specifics. e.g. 'medieval fantasy, comedy', 'Ancient Egypt, mythology', '80s high school, USA'.">
            <textarea
              defaultValue={config.theme_general ?? ""}
              rows={2}
              key={`theme_general:${revision}`}
              onBlur={(e) => writeConfig({ ...config, theme_general: e.target.value })}
              style={{ ...inputStyle, fontSize: 13, lineHeight: 1.5, resize: "vertical" }} />
          </Field>

          <Field label="Theme elaboration"
            hint="The specific version of the same setting — genuinely separate writing from the box above, not a longer version of it. Names the actual visual vocabulary (architecture, materials, what the cast wears) that keeps this from defaulting to the generic version of its genre — an elf village needs this to avoid rendering as a human one, even though both are 'medieval fantasy'.">
            <textarea
              defaultValue={config.theme_elaborated ?? ""}
              rows={4}
              key={`theme_elaborated:${revision}`}
              onBlur={(e) => writeConfig({ ...config, theme_elaborated: e.target.value })}
              style={{ ...inputStyle, fontSize: 13, lineHeight: 1.5, resize: "vertical" }} />
          </Field>

          <Field
            label="Art style"
            hint={engine === "flux"
              ? "Adventure v2 follows written direction closely, so be specific and imperative. Colour limits and dithering instructions work well here."
              : "Shared by every picture drawn with Adventure v1. The look, not the subject."}>
            <textarea
              defaultValue={config[styleKey] ?? ""}
              rows={4}
              key={`${styleKey}:${revision}`}
              onBlur={(e) => writeConfig({ ...config, [styleKey]: e.target.value })}
              style={{ ...inputStyle, fontSize: 13, lineHeight: 1.5, resize: "vertical" }} />
          </Field>

          {kind === "cover" && (
            <Field label="Byline"
              hint="Always the world's real title and your real account name — never free text — so a rename or a name change carries through without a redraw.">
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
                <label style={{ display: "flex", alignItems: "center", gap: 7, fontFamily: T.mono, fontSize: 12, color: T.boneDim, cursor: "pointer" }}>
                  <input type="checkbox"
                    checked={config.cover_byline !== "false"}
                    onChange={(e) => writeConfig({
                      ...config,
                      // Stored as a string like every other config field —
                      // saveArtConfig calls .trim() on every value, which
                      // would throw on a real boolean. Checked (the
                      // default) is stored as "" so it drops out entirely
                      // rather than taking up a key for nothing.
                      cover_byline: e.target.checked ? "" : "false",
                    })} />
                  Include "by {me.name || "you"}"
                </label>
              </div>
              <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, fontStyle: "italic" }}>
                {(config.cover_byline === "false" || config.cover_byline === false)
                  ? `splash screen of a game with the title '${title || "…"}'`
                  : `splash screen of a game with the title '${title || "…"}' by '${me.name || "…"}'`}
              </div>
            </Field>
          )}

          <Field
            label={kind === "cover" ? "Framing for the splash screen" : `Framing for ${KIND_LABEL[kind] ?? kind}`}
            hint={kind === "cover"
              ? "Added after the title and byline above. This is where the actual visual direction goes — composition, mood, what the scene shows."
              : "How this kind is composed. Rooms are wide views, characters are portraits, items are single objects."}>
            <textarea
              defaultValue={config[kind] ?? ""}
              rows={3}
              key={`${kind}:${revision}`}
              onBlur={(e) => writeConfig({ ...config, [kind]: e.target.value })}
              placeholder={kind === "cover" ? "e.g. dramatic key art, one figure against a landscape," : undefined}
              style={{ ...inputStyle, fontSize: 13, lineHeight: 1.5, resize: "vertical" }} />
          </Field>

          {engine === "pixel" && (
          <div style={{ borderTop: `1px solid ${T.edge}`, paddingTop: 16, marginTop: 4 }}>
            <Field label="Avoid, everywhere"
              hint="Sent as the negative prompt on every picture in this world.">
              <textarea
                defaultValue={config.neg ?? ""}
                key={`neg:${revision}`}
                rows={2}
                onBlur={(e) => writeConfig({ ...config, neg: e.target.value })}
                style={{ ...inputStyle, fontSize: 13, lineHeight: 1.5, resize: "vertical" }} />
            </Field>

            <Field
              label={`Avoid, ${(KIND_LABEL[kind] ?? kind).toLowerCase()} only`}
              hint={kind === "item"
                ? "Items go wrong in one particular way: the model draws a sheet of sprites or an inventory screen instead of the object. Most of this list is there to stop that."
                : "Added to the list above when drawing this kind."}>
              <textarea
                defaultValue={config[`neg_${kind}`] ?? ""}
                rows={3}
                key={`neg_${kind}:${revision}`}
                onBlur={(e) => writeConfig({ ...config, [`neg_${kind}`]: e.target.value })}
                style={{ ...inputStyle, fontSize: 13, lineHeight: 1.5, resize: "vertical" }} />
            </Field>
          </div>
          )}

          <Btn kind="ghost" onClick={chooseDefaultOption}>
            reset to defaults
          </Btn>
        </div>
      )}
    </div>

    <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 10, flexWrap: "wrap" }}>
      <p style={{ fontFamily: T.serif, fontSize: 15.5, color: T.boneDim, lineHeight: 1.55, margin: 0, flex: 1, minWidth: 240 }}>
        {kind === "orphan"
          ? "These were drawn for something a change removed. They are kept because you paid for them: undo the change, or bring the character or item back under the same name, and the picture reattaches itself."
          : "Lock one once you are happy with it. Locked pictures are skipped by redraws, including bulk ones."}
      </p>
      {missing.length > 0 && (
        <Btn onClick={() => { setError(null); setQueue(missing.slice(0, affordable).map((e) => e.id)); }}
          disabled={busy || batch < 1}>
          {busy
            ? "drawing" + (queue.length ? " \u00b7 " + queue.length + " left" : "")
            : "Draw " + batch + " missing \u00b7 " + money(batch * COST)}
        </Btn>
      )}
      <button onClick={() => setLayout(layout === "grid" ? "list" : "grid")} className="pf-btn"
        title={layout === "grid" ? "Switch to list view" : "Switch to grid view"}
        style={{ width: 34, height: 34, flexShrink: 0, borderRadius: 2, cursor: "pointer",
          background: "transparent", border: "1px solid " + T.edge,
          color: T.boneDim, display: "inline-flex", alignItems: "center", justifyContent: "center" }}>
        <Glyph name={layout === "grid" ? "list" : "grid"} />
      </button>
    </div>

    {affordable < 1 && (
      <p style={{ fontFamily: T.mono, fontSize: 11, color: T.clay, margin: "0 0 14px" }}>
        Not enough left to draw anything. One picture here costs {money(COST)}.
      </p>
    )}
    {error && (
      <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, lineHeight: 1.7,
        border: "1px solid " + T.clay + "44", padding: 12, borderRadius: 2, margin: "0 0 16px" }}>
        {error}
      </p>
    )}

    {/* Splash screen, ending, and badge are each the one entry that ever
        exists of their kind — a grid cell never made sense for something
        there is only ever one of. All three always render as a
        full-width row, the same shape as list mode, regardless of the
        grid/list toggle above. */}
    <div style={(layout === "grid" && kind !== "cover" && kind !== "ending" && kind !== "badge")
      ? { display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))", gap: 18 }
      : { display: "flex", flexDirection: "column", gap: 12 }}>
      {shown.map((e) => {
        const lockButton = (
          <button onClick={() => toggleLock(e)}
            title={e.locked ? "Unlock to allow redraws" : "Lock to protect from redraws"} className="pf-btn"
            style={{ position: "absolute", top: 7, right: 7, width: 27, height: 27, borderRadius: 2, cursor: "pointer",
              display: "flex", alignItems: "center", justifyContent: "center",
              background: e.locked ? T.ochre : "rgba(20,22,17,.72)", border: "1px solid " + (e.locked ? T.ochre : T.edge),
              color: e.locked ? "#221D0C" : T.bone, fontSize: 12, lineHeight: 1 }}>
            {e.locked ? "\ud83d\udd12" : "\ud83d\udd13"}
          </button>
        );

        const nameRow = (
          <div style={{ display: "flex", alignItems: "baseline", gap: 8, marginTop: layout === "grid" ? 8 : 0 }}>
            <span style={{ fontFamily: T.serif, fontSize: 15.5, flex: 1, minWidth: 0 }}>{e.name}</span>
            {kind === "orphan" ? (
              <button className="pf-btn"
                onClick={async () => {
                  try {
                    await deleteArt(e.id);
                    setEntries((es) => es.filter((x) => x.id !== e.id));
                  } catch (err) { setError(err.message); }
                }}
                style={{ background: "none", border: "none", padding: 0, fontFamily: T.mono,
                  fontSize: 11, color: T.clay, cursor: "pointer" }}>
                delete for good
              </button>
            ) : (<>
            <button onClick={() => draw(e)} disabled={e.locked || busy || me.balance < COST} className="pf-btn"
              style={{ background: "none", border: "none", padding: 0, fontFamily: T.mono, fontSize: 11,
                color: e.locked ? T.edge : T.boneDim, cursor: (e.locked || busy) ? "not-allowed" : "pointer" }}>
              {drawing === e.id ? "drawing" : (e.art ? "redraw \u00b7 " : "draw \u00b7 ") + money(COST)}
            </button>
            {e.art && !e.locked && (
              <button onClick={() => setEditOpen((s) => ({ ...s, [e.id]: !s[e.id] }))} className="pf-btn"
                style={{ background: "none", border: "none", padding: 0, fontFamily: T.mono, fontSize: 11,
                  color: editOpen[e.id] ? T.ochre : T.boneDim, cursor: "pointer" }}>
                edit
              </button>
            )}
            </>
            )}
          </div>
        );

        // Beneath the name row — a plain-language instruction for
        // changing the existing picture in place, rather than
        // generating a fresh one from the stored prompt. Only ever
        // shown when there's an actual picture to edit.
        const editReferenceable = entries.filter((x) => x.art && x.id !== e.id);
        const editCost = editReference[e.id] ? EDIT_REFERENCE_COST_CENTS : EDIT_COST_CENTS;
        const editRow = e.art && editOpen[e.id] && (
          <div style={{ marginTop: 8, padding: "10px 12px", border: "1px solid " + T.edge, borderRadius: 2 }}>
            <textarea
              value={editText[e.id] || ""}
              onChange={(ev) => setEditText((t) => ({ ...t, [e.id]: ev.target.value }))}
              rows={2}
              placeholder="What should change? e.g. 'make the sky more orange' or 'remove the lantern on the left'"
              style={{ ...inputStyle, fontSize: 12.5, lineHeight: 1.5, resize: "vertical", marginBottom: 8 }} />
            {editReferenceable.length > 0 && (
              <div style={{ marginBottom: 8 }}>
                <button onClick={() => setEditReferenceOpen((s) => ({ ...s, [e.id]: !s[e.id] }))} className="pf-btn"
                  style={{ background: "none", border: "none", padding: 0, cursor: "pointer",
                    fontFamily: T.mono, fontSize: 10.5, color: T.boneDim, marginBottom: editReferenceOpen[e.id] ? 6 : 0 }}>
                  {editReferenceOpen[e.id] ? "\u2212 " : "+ "}
                  {"Optional, experimental \u2014 base the change on another picture"}
                </button>
                {editReferenceOpen[e.id] && (
                  <select value={editReference[e.id] ?? ""}
                    onChange={(ev) => setEditReference((s) => ({ ...s, [e.id]: ev.target.value }))}
                    style={{ ...inputStyle, width: "auto", fontSize: 11.5, padding: "6px 8px" }}>
                    <option value="">{"Choose a picture\u2026"}</option>
                    {editReferenceable.map((x) => (
                      <option key={x.id} value={x.id}>{`${KIND_LABEL[x.kind] ?? x.kind} \u2014 ${x.name}`}</option>
                    ))}
                  </select>
                )}
              </div>
            )}
            <div style={{ display: "flex", gap: 6, marginBottom: 8 }}>
              {[["openai", "Editor v1"], ["fal", "Editor v2"]].map(([v, label]) => (
                <button key={v} onClick={() => setEditEngine((s) => ({ ...s, [e.id]: v }))} className="pf-btn"
                  style={{ padding: "6px 10px", borderRadius: 2, cursor: "pointer", background: "transparent",
                    fontFamily: T.mono, fontSize: 10.5,
                    color: (editEngine[e.id] || "openai") === v ? T.bone : T.boneDim,
                    border: `1px solid ${(editEngine[e.id] || "openai") === v ? T.ochre : T.edge}` }}>
                  {label}
                </button>
              ))}
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <button onClick={() => editImage(e)}
                disabled={editingImage === e.id || !(editText[e.id] || "").trim() || me.balance < editCost}
                className="pf-btn"
                style={{ background: "none", border: "1px solid " + T.edge, borderRadius: 2, cursor: "pointer",
                  padding: "8px 12px", fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>
                {editingImage === e.id ? "editing\u2026" : `Apply edit \u00b7 ${money(editCost)}`}
              </button>
              <button onClick={() => { setEditOpen((s) => ({ ...s, [e.id]: false })); setEditText((t) => ({ ...t, [e.id]: "" })); setEditReference((s) => ({ ...s, [e.id]: "" })); setEditReferenceOpen((s) => ({ ...s, [e.id]: false })); }}
                className="pf-btn"
                style={{ background: "none", border: "none", padding: 0, fontFamily: T.mono, fontSize: 11,
                  color: T.boneDim, cursor: "pointer" }}>
                cancel
              </button>
            </div>
          </div>
        );
        // overrides for how much of the world's shared theme this one
        // picture uses, and how it handles ambient people, independent
        // of each other. Null on either means "use this kind's own
        // default" (see DEFAULT_THEME_LEVEL/DEFAULT_PEOPLE_LEVEL
        // server-side) — shown here as an actual selectable option
        // rather than silently picking one, so a creator can always
        // return to the default explicitly.
        const isAdvancedOpen = Boolean(advancedOpen[e.id]);
        const advancedRow = (
          <div style={{ paddingTop: 6 }}>
            <button onClick={() => setAdvancedOpen((s) => ({ ...s, [e.id]: !s[e.id] }))} className="pf-btn"
              style={{ background: "none", border: "none", padding: 0, cursor: "pointer",
                fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>
              {isAdvancedOpen ? "\u2212 hide" : "+ show"} advanced
            </button>
            {isAdvancedOpen && (
              <div style={{ marginTop: 10, display: "flex", flexDirection: "column", gap: 14 }}>
                <div>
                  <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginBottom: 6 }}>
                    Theme — how much of the world's setting this picture uses
                  </div>
                  <div style={{ display: "flex", gap: 6 }}>
                    {[["general", "General"], ["detailed", "Detailed"], ["none", "None"]].map(([v, label]) => (
                      <button key={v} className="pf-btn"
                        onClick={() => setLevels(e, v, e.peopleLevel ?? null)}
                        style={{ padding: "6px 10px", borderRadius: 2, cursor: "pointer", background: "transparent",
                          fontFamily: T.mono, fontSize: 11.5,
                          color: (e.themeLevel ?? null) === v ? T.bone : T.boneDim,
                          border: `1px solid ${(e.themeLevel ?? null) === v ? T.ochre : T.edge}` }}>
                        {label}
                      </button>
                    ))}
                    <button className="pf-btn" onClick={() => setLevels(e, null, e.peopleLevel ?? null)}
                      title="Use this kind's own default instead of choosing one here."
                      style={{ padding: "6px 10px", borderRadius: 2, cursor: "pointer", background: "transparent",
                        fontFamily: T.mono, fontSize: 11.5,
                        color: e.themeLevel == null ? T.bone : T.boneDim,
                        border: `1px solid ${e.themeLevel == null ? T.ochre : T.edge}` }}>
                      (default)
                    </button>
                  </div>
                </div>

                <div>
                  <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginBottom: 6 }}>
                    People — how this picture handles anyone else in the scene
                  </div>
                  <div style={{ display: "flex", gap: 6 }}>
                    {[["detailed", "Detailed"], ["normal", "Normal"], ["none", "None"]].map(([v, label]) => (
                      <button key={v} className="pf-btn"
                        onClick={() => setLevels(e, e.themeLevel ?? null, v)}
                        style={{ padding: "6px 10px", borderRadius: 2, cursor: "pointer", background: "transparent",
                          fontFamily: T.mono, fontSize: 11.5,
                          color: (e.peopleLevel ?? null) === v ? T.bone : T.boneDim,
                          border: `1px solid ${(e.peopleLevel ?? null) === v ? T.ochre : T.edge}` }}>
                        {label}
                      </button>
                    ))}
                    <button className="pf-btn" onClick={() => setLevels(e, e.themeLevel ?? null, null)}
                      title="Use this kind's own default instead of choosing one here."
                      style={{ padding: "6px 10px", borderRadius: 2, cursor: "pointer", background: "transparent",
                        fontFamily: T.mono, fontSize: 11.5,
                        color: e.peopleLevel == null ? T.bone : T.boneDim,
                        border: `1px solid ${e.peopleLevel == null ? T.ochre : T.edge}` }}>
                      (default)
                    </button>
                  </div>
                  {kind === "room" && (
                    <div style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim, marginTop: 6, fontStyle: "italic" }}>
                      {e.crowd ? `"Detailed" uses: ${e.crowd}` : "No crowd text was written for this room."}
                    </div>
                  )}
                </div>

                {(() => {
                  const referenceable = entries.filter((x) => x.art && x.id !== e.id);
                  return (
                    <div>
                      <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginBottom: 6 }}>
                        {kind === "mob"
                          ? "Match this character's look to another picture — e.g. a room scene they appear in — instead of inventing their appearance fresh"
                          : "Draw this to match another picture's visual style, setting, or a specific subject in it — instead of inventing it fresh"}
                      </div>
                      {referenceable.length === 0 ? (
                        <div style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim, fontStyle: "italic" }}>
                          Nothing's been drawn yet to reference.
                        </div>
                      ) : (
                        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                          <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
                            <select value={referencePicked[e.id] ?? ""}
                              onChange={(ev) => setReferencePicked((s) => ({ ...s, [e.id]: ev.target.value }))}
                              style={{ ...inputStyle, width: "auto", fontSize: 12 }}>
                              <option value="">{"Choose a picture\u2026"}</option>
                              {referenceable.map((x) => (
                                <option key={x.id} value={x.id}>{`${KIND_LABEL[x.kind] ?? x.kind} \u2014 ${x.name}`}</option>
                              ))}
                            </select>
                          </div>
                          {referencePicked[e.id] && (
                            <input type="text" value={referencePointer[e.id] || ""}
                              onChange={(ev) => setReferencePointer((s) => ({ ...s, [e.id]: ev.target.value }))}
                              placeholder={kind === "mob"
                                ? "If more than one figure is in that picture, say which one — e.g. 'the female elf archer on the left' or 'the horse, not the man'"
                                : "If there's more than one thing in that picture, say which one you mean — e.g. 'the statue in the fountain'"}
                              style={{ ...inputStyle, fontSize: 12 }} />
                          )}
                          <button onClick={() => useReference(e)}
                            disabled={!referencePicked[e.id] || generatingWithRef === e.id || me.balance < EDIT_COST_CENTS}
                            className="pf-btn"
                            style={{ background: "none", border: "1px solid " + T.edge, borderRadius: 2, cursor: "pointer",
                              padding: "8px 12px", fontFamily: T.mono, fontSize: 11, color: T.boneDim, alignSelf: "flex-start" }}>
                            {generatingWithRef === e.id ? "generating\u2026" : `Generate from reference \u00b7 ${money(EDIT_COST_CENTS)}`}
                          </button>
                        </div>
                      )}
                    </div>
                  );
                })()}

                {isAdmin && (kind === "room" || kind === "cover" || kind === "ending" || kind === "mob") && (
                  <label className="pf-btn"
                    style={{ background: "none", border: "none", padding: 0, fontFamily: T.mono, fontSize: 11,
                      color: T.boneDim, cursor: uploading === e.id ? "default" : "pointer", alignSelf: "flex-start" }}>
                    {uploading === e.id ? "uploading\u2026" : "upload image"}
                    <input type="file" accept="image/png,image/jpeg,image/webp" style={{ display: "none" }}
                      disabled={uploading === e.id}
                      onChange={(ev) => { upload(e, ev.target.files?.[0]); ev.target.value = ""; }} />
                  </label>
                )}

                {/* Rooms only — a looping background video that plays
                    over the static image once it's actually loaded.
                    Remove only appears once a video genuinely exists. */}
                {isAdmin && kind === "room" && (
                  <div style={{ display: "flex", gap: 14, alignItems: "center", flexWrap: "wrap" }}>
                    <label className="pf-btn"
                      style={{ background: "none", border: "none", padding: 0, fontFamily: T.mono, fontSize: 11,
                        color: T.boneDim, cursor: uploadingVideo === e.id ? "default" : "pointer", alignSelf: "flex-start" }}>
                      {uploadingVideo === e.id ? "uploading\u2026" : e.hasVideo ? "replace video" : "upload video"}
                      <input type="file" accept="video/mp4,video/webm" style={{ display: "none" }}
                        disabled={uploadingVideo === e.id}
                        onChange={(ev) => { uploadVideo(e, ev.target.files?.[0]); ev.target.value = ""; }} />
                    </label>
                    {e.hasVideo && (
                      <button onClick={() => removeVideo(e)} disabled={removingVideo === e.id} className="pf-btn"
                        style={{ background: "none", border: "none", padding: 0, fontFamily: T.mono, fontSize: 11,
                          color: T.clay, cursor: removingVideo === e.id ? "default" : "pointer" }}>
                        {removingVideo === e.id ? "removing\u2026" : "remove video"}
                      </button>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>
        );

        // Below the prompt textarea, not up near title/redraw/upload —
        // keeps the top row clean for the actions someone uses on every
        // picture, and puts this rarer, admin-only action next to the
        // text it actually changes instead of sharing space above it.
        const promptToolsRow = isAdmin && (kind === "ending" || kind === "badge") && (
          <div style={{ paddingTop: 4 }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: 12 }}>
              {e.prevPrompt != null && (
                <button onClick={() => undoPrompt(e)} className="pf-btn"
                  style={{ background: "none", border: "none", padding: 0, fontFamily: T.mono, fontSize: 11,
                    color: T.boneDim, cursor: "pointer" }}>
                  undo prompt
                </button>
              )}
              <button onClick={() => regeneratePrompt(e, kind)} disabled={regeneratingPromptFor === e.id}
                className="pf-btn"
                style={{ background: "none", border: "none", padding: 0, fontFamily: T.mono, fontSize: 11,
                  color: T.ochre, cursor: regeneratingPromptFor === e.id ? "default" : "pointer" }}>
                {regeneratingPromptFor === e.id
                  ? "writing\u2026"
                  : kind === "ending" ? "regenerate ending prompt" : "generate badge prompt"}
              </button>
            </div>
            {promptNote[e.id] && (
              <div style={{ textAlign: "right", marginTop: 4 }}>
                <span style={{ fontFamily: T.mono, fontSize: 10.5, color: T.moss }}>{promptNote[e.id]}</span>
              </div>
            )}
          </div>
        );

        const promptRow = (
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", paddingTop: 2 }}>
            {layout === "grid" ? (
              <button onClick={() => setEditing(editing === e.id ? null : e.id)} className="pf-btn"
                style={{ background: "none", border: "none", padding: 0, fontFamily: T.mono, fontSize: 10.5,
                  color: T.edge, cursor: "pointer" }}>
                {editing === e.id ? "hide prompt" : "edit prompt"}
              </button>
            ) : <span />}

            {e.prevUrl && kind !== "orphan" && (
              <button onClick={() => toggleViewing(e)} disabled={swapping === e.id} className="pf-btn"
                style={{ background: "none", border: "none", padding: 0, fontFamily: T.mono, fontSize: 10.5,
                  color: T.ochre, cursor: swapping === e.id ? "default" : "pointer" }}>
                {swapping === e.id ? "\u2026" : isViewingPrev(e.id) ? "Redo" : "Undo"}
              </button>
            )}
          </div>
        );

        // Rooms alone have a second, genuinely separate prompt written
        // specifically for the pixel engine — shown and edited instead
        // of the shared one whenever pixel is the currently selected
        // engine for this tab, since editing the shared prompt while
        // looking at a pixel draw would silently change nothing about
        // what pixel actually uses.
        const usingPixelPrompt = kind === "room" && engine === "pixel";
        const textarea = (
          <div>
            {usingPixelPrompt && (
              <div style={{ fontFamily: T.mono, fontSize: 10.5, color: T.ochre, marginTop: 6, marginBottom: -2 }}>
                Adventure v1 prompt — separate from the one Adventure v2 uses
              </div>
            )}
            <textarea
              defaultValue={usingPixelPrompt ? e.promptPixel : e.prompt}
              key={`${e.id}:${usingPixelPrompt ? "pixel" : "flux"}:${revision}`}
              rows={layout === "grid" ? 4 : 5}
              onBlur={(ev) => savePrompt(e, ev.target.value, usingPixelPrompt)}
              placeholder={usingPixelPrompt
                ? "Who's here and what they're doing, plus a plain background line"
                : "What the picture should show"}
              style={{ ...inputStyle, fontSize: 12.5, lineHeight: 1.5, marginTop: 6, resize: "vertical" }} />
          </div>
        );

        // Admin only — the exact text the model actually receives, joined
        // together from style + framing + this box, computed server-side
        // by the same real code a draw uses rather than a second copy of
        // the stitching logic here that could quietly drift out of sync.
        const finalPromptBlock = isAdmin && kind !== "orphan" && (
          <div style={{ marginTop: 6 }}>
            <button onClick={() => toggleFinalPreview(e)} className="pf-btn"
              style={{ background: "none", border: "none", padding: 0, fontFamily: T.mono, fontSize: 10.5,
                color: T.ochre, cursor: "pointer" }}>
              {finalPreview[e.id] !== undefined ? "hide final prompt" : "show final prompt"}
            </button>
            {finalPreview[e.id] !== undefined && (
              <div style={{ marginTop: 6, padding: "10px 12px", border: "1px solid " + T.ochre + "66",
                borderRadius: 2, fontFamily: T.mono, fontSize: 11, lineHeight: 1.7, color: T.boneDim }}>
                {finalPreview[e.id] === "loading" ? (
                  "loading\u2026"
                ) : typeof finalPreview[e.id] === "string" ? (
                  <span style={{ color: T.clay }}>{finalPreview[e.id]}</span>
                ) : (<>
                  <div><b style={{ color: T.ochre }}>Prompt:</b> {finalPreview[e.id].prompt || "—"}</div>
                  {finalPreview[e.id].negative && (
                    <div style={{ marginTop: 4 }}>
                      <b style={{ color: T.ochre }}>Negative:</b> {finalPreview[e.id].negative || "—"}
                    </div>
                  )}
                  {finalPreview[e.id].settings && (
                    <div style={{ marginTop: 4 }}>
                      <b style={{ color: T.ochre }}>Settings:</b>{" "}
                      {Object.entries(finalPreview[e.id].settings).map(([k, v]) => `${k}: ${v}`).join(", ")}
                    </div>
                  )}
                </>)}
              </div>
            )}
          </div>
        );

        const useRow = layout === "list" || kind === "cover" || kind === "ending" || kind === "badge";

        if (useRow) {
          // Image beside everything else — the prompt is always visible
          // here rather than gated behind a toggle, since a row layout is
          // for reviewing at size, not skimming a grid.
          //
          // Every kind gets its own honest shape rather than one forced
          // box: a room or a splash is landscape and wide, a wide 16:9 box
          // stretched to at least half the row's own width; a portrait
          // keeps its natural tall ratio at a fixed width rather than
          // being squeezed into something shorter than it wants to be;
          // props and items are square and stay at the compact size that
          // already suited them. On a narrow screen the image moves above
          // the text instead of beside it, full width, since there is no
          // room to sit them side by side.
          const wide = kind === "room" || kind === "cover" || kind === "ending";
          const imgStyle = kind === "badge"
            ? { width: 220, flexShrink: 0 }                  // fixed on every layout — an oval badge on
                                                               // narrow screens would look obviously wrong
            : narrow
              ? { width: "100%" }
              : wide
                ? { flex: "0 0 50%" }
                : { width: 240, flexShrink: 0 };
          const splashOverride = kind === "badge"
            ? { paddingTop: 0, height: 220, borderRadius: "50%" }  // round on every layout, narrow included —
                                                                     // same "fixed regardless of screen" reasoning
                                                                     // as imgStyle above, checked first for the
                                                                     // same reason: narrow must not skip it.
            : narrow
              ? undefined                                    // full width, natural ratio
              : wide
                ? { paddingTop: "56.25%" }                    // 16:9, independent of the image's own width now
                : (kind === "prop" || kind === "item")
                  ? { paddingTop: 0, height: 220 }             // unchanged from before
                  : undefined;                                 // characters: natural ratio, no forcing

          return (
            <div key={e.id} style={{ display: "flex", flexDirection: narrow ? "column" : "row",
              gap: 14, background: "transparent", border: "1px solid " + T.edge, borderRadius: 2, padding: 10 }}>
              <div style={{ position: "relative", alignSelf: narrow ? "stretch" : "flex-start", ...imgStyle }}>
                <Splash seed={e.key} src={e.url}
                  fallbackSvg={!e.url && kind === "room" ? sceneFallbackSvg(e) : undefined}
                  pending={drawing === e.id || swapping === e.id}
                  ratio={ratio} style={splashOverride} />
                {e.hasVideo && playingVideoFor !== e.id && (
                  <button onClick={() => setPlayingVideoFor(e.id)}
                    title="Play video" aria-label="Play video"
                    style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,0.15)", border: "none",
                      cursor: "pointer", display: "grid", placeItems: "center" }}>
                    <span style={{ width: 44, height: 44, borderRadius: "50%", background: "rgba(20,16,8,0.75)",
                      display: "grid", placeItems: "center", fontSize: 16, color: T.bone }}>
                      {"\u25b6"}
                    </span>
                  </button>
                )}
                {e.hasVideo && playingVideoFor === e.id && (
                  <video src={e.videoUrl} autoPlay loop muted playsInline
                    onClick={() => setPlayingVideoFor(null)} title="Click to stop"
                    style={{ position: "absolute", inset: 0, width: "100%", height: "100%",
                      objectFit: "cover", cursor: "pointer" }} />
                )}
                {lockButton}
              </div>
              <div style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column" }}>
                {nameRow}
                {editRow}
                {promptRow}
                {textarea}
                {advancedRow}
                {promptToolsRow}
                {finalPromptBlock}
              </div>
            </div>
          );
        }

        return (
          <div key={e.id}>
            <div style={{ position: "relative" }}>
              <Splash seed={e.key} src={e.url}
                fallbackSvg={!e.url && kind === "room" ? sceneFallbackSvg(e) : undefined}
                pending={drawing === e.id || swapping === e.id} ratio={ratio}
                style={kind === "badge" ? { borderRadius: "50%" } : undefined} />
              {e.hasVideo && playingVideoFor !== e.id && (
                <button onClick={() => setPlayingVideoFor(e.id)}
                  title="Play video" aria-label="Play video"
                  style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,0.15)", border: "none",
                    cursor: "pointer", display: "grid", placeItems: "center" }}>
                  <span style={{ width: 44, height: 44, borderRadius: "50%", background: "rgba(20,16,8,0.75)",
                    display: "grid", placeItems: "center", fontSize: 16, color: T.bone }}>
                    {"\u25b6"}
                  </span>
                </button>
              )}
              {e.hasVideo && playingVideoFor === e.id && (
                <video src={e.videoUrl} autoPlay loop muted playsInline
                  onClick={() => setPlayingVideoFor(null)} title="Click to stop"
                  style={{ position: "absolute", inset: 0, width: "100%", height: "100%",
                    objectFit: "cover", cursor: "pointer" }} />
              )}
              {lockButton}
            </div>
            {nameRow}
            {editRow}
            {promptRow}
            {editing === e.id && textarea}
            {editing === e.id && advancedRow}
            {editing === e.id && promptToolsRow}
            {editing === e.id && finalPromptBlock}
          </div>
        );
      })}
    </div>
  </>);
}


/* Item and room names arrive lowercase from the world data ("waxy lemon"),
   because that is how they read inside a sentence. In the chrome they are
   labels, so they get capitals. */
